<?php if(!in_array($data['status'],['WITHDRAWN','HIRED','REJECTED'],true)): ?><button class="ghost" data-action="/applications/<?= e($data['id']) ?>" data-method="DELETE" data-confirm="Bạn chắc chắn muốn rút đơn ứng tuyển này?" data-reload>Rút hồ sơ</button><?php endif; ?>
