<?php elseif(!in_array($data['status'],['HIRED','REJECTED','WITHDRAWN'],true)): ?><section class="panel section"><h2><?= $isAi?'Gợi ý hành động cho HR':'Quản lý hồ sơ' ?></h2><?php if($isAi&&$score):$suggestion=\Platform\Services\ApplicationView::suggestion($data); ?><p><strong><?= e($suggestion['title']) ?></strong></p><p class="muted"><?= e($suggestion['note']) ?></p><form data-api="/applications/<?= e($data['id']) ?>/status" data-method="PATCH" data-reload><input type="hidden" name="status" value="<?= e($suggestion['status']) ?>"><label>Ghi chú HR<input name="note" value="<?= e($suggestion['note']) ?>"></label><button type="submit">Xác nhận gợi ý</button></form><?php endif; ?><div class="grid two">
<form data-api="/applications/<?= e($data['id']) ?>/status" data-method="PATCH" data-reload><label>Trạng thái<select name="status"><?php foreach(['HR_REVIEW','INTERVIEW','OFFER','HIRED','REJECTED'] as $status): ?><option value="<?= e($status) ?>" <?= $data['status']===$status?'selected':'' ?>><?= e($labels[$status]) ?></option><?php endforeach; ?></select></label><label>Ghi chú<input name="note"></label><button type="submit">Cập nhật</button></form>
<form data-api="/applications/<?= e($data['id']) ?>/schedule-interview" data-reload><label>Ngày phỏng vấn<input type="datetime-local" name="interviewAt" required></label><label>Ghi chú<input name="note"></label><button type="submit">Lên lịch phỏng vấn</button></form>
